import { ChevronLeft, ChevronRight, MapPin } from "lucide-react";
import { useEffect, useMemo, useState } from "react";
import { eventDate, eventRequest } from "../../services/eventApi";
import "./EventCalendar.css";
export default function EventCalendar(){const [cursor,setCursor]=useState(new Date()),[events,setEvents]=useState([]),[selected,setSelected]=useState(new Date().toISOString().slice(0,10));useEffect(()=>{eventRequest("/vendor/events/calendar",{params:{month:cursor.getMonth()+1,year:cursor.getFullYear()}}).then(x=>setEvents(x.events||[])).catch(()=>setEvents([]))},[cursor]);const days=new Date(cursor.getFullYear(),cursor.getMonth()+1,0).getDate(),first=new Date(cursor.getFullYear(),cursor.getMonth(),1).getDay();const byDate=useMemo(()=>events.reduce((m,e)=>{const d=String(e.event_date).slice(0,10);(m[d]||=[]).push(e);return m},{}),[events]);const move=n=>setCursor(new Date(cursor.getFullYear(),cursor.getMonth()+n,1));return <section><header className="ec-title"><div><small>LIVE SCHEDULE</small><h1>Event Calendar</h1><p>Click a date to inspect its event schedule.</p></div><div><button onClick={()=>move(-1)}><ChevronLeft/></button><b>{cursor.toLocaleDateString("en-IN",{month:"long",year:"numeric"})}</b><button onClick={()=>move(1)}><ChevronRight/></button></div></header><section className="ec-layout"><article className="ed-panel ec-calendar"><div className="ec-week">{"Sun Mon Tue Wed Thu Fri Sat".split(" ").map(x=><b key={x}>{x}</b>)}</div><div className="ec-days">{Array.from({length:first}).map((_,i)=><i key={i}/>) }{Array.from({length:days},(_,i)=>i+1).map(day=>{const key=`${cursor.getFullYear()}-${String(cursor.getMonth()+1).padStart(2,"0")}-${String(day).padStart(2,"0")}`,items=byDate[key]||[];return <button className={`${selected===key?"selected":""} ${items.length?"booked":""}`} key={day} onClick={()=>setSelected(key)}><span>{day}</span>{items.slice(0,2).map(e=><small key={e.id}>{e.event_name}</small>)}{items.length>2&&<em>+{items.length-2} more</em>}</button>})}</div></article><aside className="ed-panel ec-agenda"><header><div><small>SELECTED DATE</small><h3>{eventDate(selected)}</h3></div></header>{(byDate[selected]||[]).map(e=><article key={e.id}><time>{String(e.start_time).slice(0,5)}</time><div><b>{e.event_name}</b><p><MapPin size={13}/>{e.venue_name}, {e.city}</p><span className={`ed-status ${e.status}`}>{e.status}</span></div></article>)}{!(byDate[selected]||[]).length&&<div className="ed-empty">No events scheduled on this date.</div>}</aside></section></section>}
